const express = require('express');
const EventEmitter = require('events');
const { authenticateCustomer } = require('../auth');
const Ticket = require('../models/Ticket');

const router = express.Router();
const chatEmitter = new EventEmitter();

router.get('/api/support/tickets/:ticketId/long-poll', authenticateCustomer, async (req, res) => {
  const { ticketId } = req.params;

  const ticket = await Ticket.findOne({ _id: ticketId, customerId: req.customer.id });
  if (!ticket) {
    return res.status(403).json({ error: 'Access denied: ticket does not belong to your account' });
  }

  const onNewMessage = (msg) => {
    res.json({ success: true, message: msg });
  };

  chatEmitter.once(`ticket:${ticketId}`, onNewMessage);

  req.on('close', () => {
    chatEmitter.removeListener(`ticket:${ticketId}`, onNewMessage);
  });
});
